    "anchor": {
      "probability": 0.18,
      "basis": "Near-term probability anchored on OPCW-confirmed CS presence and credible intelligence assessments for Ukraine (2024–2025), used as the baseline for updates."
    },
    "factor_updates": [
      {
        "factor": "Recent confirmed or credible reports of state-actor chemical weapon use in Ukraine (CS, chloropicrin)",
        "direction": "up",
        "magnitude": "strong",
        "rationale": "Direct evidence of use increases the baseline risk and informs the likelihood of additional uses before 2026."
      },
      {
        "factor": "Erosion of chemical weapons norms and enforcement challenges",
        "direction": "up",
        "magnitude": "moderate",
        "rationale": "Erosion of norms and enforcement challenges raise probability of at least one incident in a protracted conflict."
      },
      {
        "factor": "OPCW monitoring and attribution capabilities improving",
        "direction": "up",
        "magnitude": "moderate",
        "rationale": "Improved detection and reporting heighten risk visibility, potentially increasing observed probability."
      },
      {
        "factor": "Attribution uncertainty about who used the agents",
        "direction": "neutral",
        "magnitude": "weak",
        "rationale": "Uncertainty around attribution complicates risk assessment but does not by itself reduce risk; could sway responses."
      },
      {
        "factor": "Deterrence via sanctions and international response",
        "direction": "down",
        "magnitude": "moderate",
        "rationale": "Deterrence costs reduce the likelihood of future CW use, tempering total probability."
      }
    ],
    "synthesis_rationale": "Starting from an anchor of 0.18, the combination of strong positive updates from confirmed use, plus moderate positive updates from norms erosion and detection, and a countervailing deterrence effect yields a posterior near 0.47. Correlation among updates acknowledged; final calibration aligns with the stated Bayesian outcome and communicates residual uncertainty."
  }
}

